INSERT INTO `dev_log` VALUES ('2124024219819659265', 'OPERATE', '添加文章', 'SUCCESS', NULL, '127.0.0.1', '内网IP|内网IP', 'MSEdge', 'Windows 10 or Windows Server 2016', 'vip.xiaonuo.biz.modular.article.controller.BizArticleController', 'add', '/biz/article/add', '/biz/article/add', '{\"bizArticleAddParam\":\"{\\\"title\\\":\\\"测试标题\\\",\\\"cover\\\":\\\"/snowy/dev/file/download?id=2124024219492503553&sign=MjAxNjVjZTNhNzAyNWRlMGU3Njc4MTg1NGYwNDQ3MTc3ZTE0YzA0ZTZhNzAwNTVmOTMwMWRmY2U3NzNiZmFmYw==\\\",\\\"summary\\\":\\\"午后的风穿过窗沿，带着一点秋日里淡淡的干爽。阳光慢慢挪到书桌一角\\\",\\\"content\\\":\\\"<p data-id=\\\\\\\"ea908600-0800-429e-9a39-ba49446c6d16\\\\\\\">午后的风穿过窗沿，带着一点秋日里淡淡的干爽。阳光慢慢挪到书桌一角，落在摊开的书页上，字里行间都浸着温柔。不必急着追赶什么，也不用纠结还没做完的事，就安安静静地坐一会儿，听听远处隐约的风声，感受时间缓缓流淌。很多时候美好并不藏在盛大的光景里，而是藏在这些不起眼、松弛的片刻之间。</p><p data-id=\\\\\\\"877e5b87-b521-43a4-9d6c-68d51affd3e1\\\\\\\">午后的风穿过窗沿，带着一点秋日里淡淡的干爽。阳光慢慢挪到书桌一角，落在摊开的书页上，字里行间都浸着温柔。不必急着追赶什么，也不用纠结还没做完的事，就安安静静地坐一会儿，听听远处隐约的风声，感受时间缓缓流淌。很多时候美好并不藏在盛大的光景里，而是藏在这些不起眼、松弛的片刻之间。</p>\\\",\\\"category\\\":\\\"cat_mwpxeusskx7y\\\",\\\"status\\\":\\\"PUBLISHED\\\"}\"}', '{\"code\":200,\"msg\":\"操作成功\",\"traceId\":\"ba27c24a80124982a70acaf05a6231f2\"}', '2026-11-21 14:16:51', '业管', '3045022100c2266f2a71770bd09642008a9f82bae6ccb71a10708826e6bd0cd8b1ed58ad8e02206ba3c5be293f06a450b80d8157cc940c2126ed5c35ce6b4ef1177dae83cc2978', '2026-11-21 14:16:51', '-1', NULL, NULL);
